import{_ as r,a0 as a,w as l,s as u,ao as p,I as e,x as n,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"我家的 Linux 故事 | LCTT x X-CMD","titleTemplate":false,"description":"我家的 Linux 故事 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我家的 Linux 故事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我家的 Linux 故事 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210529 My family-s Linux story","title":"我家的 Linux 故事","tag":"202107","desc":""},"relativePath":"202107/20210529 My family-s Linux story.md","filePath":"[post].md"}'),m={name:"202107/20210529 My family-s Linux story.md"};function x(d,t,f,L,T,y){const o=a("Link");return l(),u("div",null,[t[15]||(t[15]=p('<h1 id="我家的-linux-故事" tabindex="-1">我家的 Linux 故事 <a class="header-anchor" href="#我家的-linux-故事" aria-label="Permalink to “我家的 Linux 故事”">​</a></h1><blockquote><p>我們在 Linux 的第一次嘗試只是一個 apt-get 的距離。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202107/25/065040z2zt9lb9fc99kcho.jpg" alt=""></p><p>我在 Linux 的第一次嘗試是那種“或許我應該試一試”的情況。</p><p>那是 1990 年代，我在一些軟盤上找到了用某種打包方式打包的紅帽發行版，我為家裏的筆記本電腦買了第二個硬盤，然後開始安裝它。這是一件有趣的實驗，但是我記得當時家人還沒有準備好在電腦上使用 Linux。轉眼到了 2005 年，我最終放棄了這種做法，買了一台可愛的東芝筆記本電腦，來運行 Windows XP。在工作中，我有一台有點年頭的 SUN SPARCStation 5，並且我不太喜歡當時整個 Solaris 的發展方向（基於 Motif 的桌面）。我真的想要用 GIMP 來完成一些這樣或那樣的項目，但是在 Solaris 上安裝 GNOME 1.x（也許是 1.4？）的曲折旅程是很有挑戰性的。所以，我實際上是在考慮跳槽到 Windows XP。但是在我的家用機上用了幾個月之後，我發現我更不喜歡在 Solaris 上運行 GNOME，所以我安裝了 Ubuntu Hoary Hedgehog 5.04，隨後在我的筆記本電腦上安裝了 Breezy Badger 5.10。這太棒了，那台擁有 3.2GHz 奔騰處理器、2GB 內存和 100GB 的硬盤的機器就在我的 SPARCStation 5 旁邊運行。</p><p>突然之間，我不再用拼湊起來的 Solaris 安裝包來試圖去讓東西運行起來，而只是用 apt-get 就可以了。並且這個時機也很好。我家庭和我從 2006 年 8 月到 2007 年 7 月居住在法國格勒諾布爾，當時我的妻子在休假。因為有了運行 Linux 的東芝筆記本，我可以帶着我的工作一起走。那個時候我在幾個大的項目上做了大量的 GIS 數據處理，我發現我可以在 PostGIS / PostgreSQL 上做同樣的事情，比我們在加拿大家中使用的昂貴得多的商業 GIS 軟件要快得多。大家都很開心，尤其是我。</p><p>這一路上發生的有趣的事情是，我們把另外兩台電腦帶到了法國 —— 我妻子的類似的東芝電腦（運行 XP，對她來説很好用）和我們孩子最近新買的東芝牌筆記本電腦，也運行 XP。也就在聖誕節過後，他們有一些朋友過來，無意中在他們的電腦上安裝了一個討厭的、無法清除的病毒。經過幾個小時甚至幾天後，我的一個孩子問我：“爸爸，我們就不能安裝和你電腦上一樣的東西嗎？”然後，三個新的 Linux 用户就這樣產生了。我的兒子，29 歲了，依然是一個快樂的 Linux 用户，我猜他有第四或第五台 Linux 筆記本電腦了，最後幾台都是由 System 76 提供的。我的一個女兒三年前開始讀法學院時被迫轉換為 Windows，因為她所在的學校有一個強制性的測試框架，只能在 Windows 上運行，而且據稱會檢測虛擬機之類的東西（請不要讓我開始罵人）。而我的另一個女兒被她的公司為她買的 Macbook Air 誘惑了。</p><p>哦，好吧，不可能全都贏了吧！</p><hr>',9)),e("p",null,[t[1]||(t[1]=n("via: ",-1)),i(o,{href:"https://opensource.com/article/21/5/my-linux-story"},{default:s(()=>[...t[0]||(t[0]=[n("https://opensource.com/article/21/5/my-linux-story",-1)])]),_:1})]),e("p",null,[t[6]||(t[6]=n("作者：",-1)),i(o,{href:"https://opensource.com/users/clhermansen"},{default:s(()=>[...t[2]||(t[2]=[n("Chris Hermansen",-1)])]),_:1}),t[7]||(t[7]=n(" 選題：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[3]||(t[3]=[n("lujun9972",-1)])]),_:1}),t[8]||(t[8]=n(" 譯者：",-1)),i(o,{href:"https://github.com/shiboi77"},{default:s(()=>[...t[4]||(t[4]=[n("shiboi77",-1)])]),_:1}),t[9]||(t[9]=n(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[12]||(t[12]=n("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[n("Linux中國",-1)])]),_:1}),t[14]||(t[14]=n(" 榮譽推出",-1))])])}const P=r(m,[["render",x]]);export{g as __pageData,P as default};
